INSERT INTO projects (project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES ('P052-06','CN0168','6000m³/a蜂窝状失活SCR利用项目','企业验收公示索引','2025-11-11','6000废剂利用；10000再生产品自述','清洗工艺自述，污水处理链未获；附件未读','S052-17');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-01','CN0103','S052-01','共享设计规模','2.2建设规模','一期污水156.60–180、两期250.7–287m³/h，设计180/300；清净废水208.2–261.2/382.4–483.3，中水450/350/800m³/h，设计回收85%。气化、其他生产及生活初雨共享，非催化剂专属。地址白银区王岘镇东星村苏家墩201号。2500t/a催化剂设计已录不重复。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-02','CN0103','S052-02','零排放设计要求','2.2招标检索摘录','主要处理二级RO浓水，分盐浓缩蒸发回用；总产水回收≥85%，TDS≥90000mg/L时污水≤18m³/h，NaCl目标煤化工副产干盐一级品；非实测，正文超时。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-03','CN0103','S052-03','一期试运证据','2025-10-16验收服务采购','采购人列污水、中水、零排放、脱盐水等已建试运行；一期产能清单不含催化剂，不能据共享试运判催化剂投产。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-04','CN0103','S052-04','二期调试证据','2026-05-01政府报道','一期2025年3月开车；二期脱盐水、污水、中水、零排放调试运行，9月底开车为当时计划。未核当前实际产量与膜清单。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-05','CN0103','S052-05','中标线索','2024-07-01索引','二期污水中水工程中标公告存在，正文超时未得中标价或单位；不填费用。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-06','CN0019','W01B2S09','一期分股及负荷','表3.2.5-3/4，pp80–82；3.1.5','19股含蒸汽冷凝回用，净纳管62116.7t/a；表3.2.5-4另6.212万m³/a。铬、锡、银钡预处理单元能力已录；正文称重金属处理达标后与其他水合并入综合站，旧图有重金属直接总排支路，保留差异；制水二级RO10t/h、产水率>70%为公辅而非废水膜。含重金属污泥2t/a设计及其他泥50t/a设计，非实绩。截图超时。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-07','CN0003','W06S18','2024实际排放范围和负荷','表2-11/12 p60','2025报告转引2024在线数据及执行报告，五项全年范围、九项季度/年度量及pH统计。报告称全部达标；仅转录不独立验证全年数据。总排口经稳定塘园区排入长江，非HTS专属。2024改性膜过滤是工艺物料洗涤，后接低温减压蒸发；原报告部分设备安装未完成，非现行BMED证据。截图超时。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-08','CN0199','S052-06','正式批复新增分流细节','平环审〔2024〕22号第四条3/5，截图第2页','活化、洗涤、尾气喷淋浓水沉淀后输尼龙科技，喷淋循环仅少量浓水定期外排；生活化粪池后市政。沉渣含碱及微量催化剂检修清理水封桶装资质处置；项目总投资5347.36万元不是污水专款；非实际。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-09','CN0304','S052-09','二期审批进度','2026-07-10政府报道','称二期稀贵金属循环利用项目2026年5月完成环评审批；设备定制，实际生产污水工艺仍未知。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-10','CN0305','S052-07','研发项目分股','拟审批公示第二节废水及固废','预处理池、废酸系统、清水池、事故池；样品尾液分类转另项目贵金属提取；实验废酸中和后入系统；废RO膜和滤芯由厂家回收，未注明RO用途，不当废水膜；结晶盐及沉降物鉴别前危废。与CN0304生产线分开。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-11','CN0288','S052-10','正式审批公告','2022-05-05','正式审批公告补证，报告原件过大，未获得定量水量；不以转载断裂数字填水质。','WEB_PRIMARY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-12','CN0010','S052-15','反渗透采购边界','公开索引标题','南京有限2026年8月锄禾反渗透膜计划预成交；打开跳首页，未核具体厂区、膜规格、水用途或实际装机，不建立废水膜设备记录。','WEB_COMPANY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-13','CN0168','S052-17','回收项目验收及规模','官网索引2025-07-09/11-11','6000m³/a蜂窝废SCR利用项目验收公示，企业称超声清洗后调配生产再生剂、年产能力10000m³；厂址和报告正文未核，保留候选，不认定工厂实际在产、实际膜或污水工艺。','WEB_COMPANY','公开正文/检索摘录；原件未归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N052-14','CN0002','S052-16','框架药剂采购','招标结果索引','60t阳离子PAM框架结果，非实际耗药/支付价；与已录1400及620吨不同项目，不叠加为实际消耗。','WEB_COMPANY','公开正文/检索摘录；原件未归档','2026-11-28');
